INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261109-trump-60-minutes', 'trump-60-minutes-interview-midterm-losses-iran-war-deportations-too-tough-cabinet-changes', 'newsroom', 'news_story', 'white-house', 'EDITORIAL_REVIEW', 0, 'On 60 Minutes, Trump links the midterm losses to the Iran war and gas prices and says his deportations may have been "too tough"', 'The interview with Ross Douthat was recorded at the White House on Friday, Nov. 6, and aired on Sunday, Nov. 8. Trump said he would attack Iran again and expects "maybe a few changes" to his Cabinet.', 'President Trump told CBS News'' *60 Minutes* that the Iran war, higher gas prices and public opposition to Israel hurt Republicans in the Tuesday, Nov. 3, midterms, in which Democrats won control of both chambers of Congress.

The interview, conducted by correspondent Ross Douthat, was recorded at the White House on Friday, Nov. 6, and aired on Sunday, Nov. 8, according to the transcript CBS News published. About an hour after it was recorded, Trump replaced chief of staff Susie Wiles with Stephen Miller.

## On the losses

Trump noted that he was not on the ballot himself. Asked whether voters had rejected the candidates he endorsed, he said, "I think they didn''t vote, really." He defended the economy but conceded "bad messaging," CBS News reported.

He said he did not disagree with Vice President JD Vance''s post blaming the war for the losses, but he defended the decision to attack Iran and said he was not looking to escalate. Asked whether he would make the same choice again, he gave an "emphatic yes," according to a CBS News summary of the interview.

## Immigration

Trump said his deportation policy may have been "too tough." He suggested a deal for longtime undocumented workers he called "good people," while continuing to remove criminals, and he gave himself "an A+" for closing the border. CBS News noted that 58% of voters in exit polling said the administration''s immigration actions had gone too far.

## The Cabinet and 2028

Asked whether he would fire anyone, Trump said, "Little bit," and that he would make "maybe a few changes," though he said he loves his Cabinet. He said he has confidence in Defense Secretary Pete Hegseth, who faces an impeachment push in the House now that Congress is back.

Trump said he would probably endorse a successor in 2028, though "not necessarily," and praised Secretary of State Marco Rubio. He added that he might be "better off not getting involved."', 'Boston Daily Staff', 'https://upload.wikimedia.org/wikipedia/commons/thumb/4/42/View_from_terrace,_White_House_LCCN2013651487.jpg/1280px-View_from_terrace,_White_House_LCCN2013651487.jpg', 'View from the terrace of the White House, early 1900s (file). Photo: Barnett McFee Clinedinst / Library of Congress via Wikimedia Commons, public domain', 'public_domain', 'newsroom', 'content/2026-11-09.sql', 8, 0, 'newsroom-assistant', '2026-11-09T10:50:00.000Z', '2026-11-09T10:50:00.000Z');
