INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261109-senate-counts', 'alaska-senate-peltola-sullivan-couple-hundred-votes-dunleavy-mississippi-colom-deadlines', 'newsroom', 'news_story', 'elections', 'EDITORIAL_REVIEW', 0, 'Alaska Gov. Dunleavy calls the Peltola-Sullivan race "very close," with the final count due on Wednesday, Nov. 25', 'Mary Peltola leads Sen. Dan Sullivan by "a couple of hundred votes," the governor said on Sunday, Nov. 8. In Mississippi, Tuesday, Nov. 10, is the last day for mail ballots and ID checks in the Colom-Hyde-Smith race.', 'Alaska''s Senate race between Democrat Mary Peltola and Republican Sen. Dan Sullivan remains too close to call, and Gov. Mike Dunleavy said on Sunday, Nov. 8, that the final count will not come until Wednesday, Nov. 25.

Speaking in a radio interview, Dunleavy called the race "very close" and said Peltola leads by "a couple of hundred votes," The Hill reported. Decision Desk HQ had Peltola at just over 48% and Sullivan at 47.9%, with about 70% of expected votes counted.

## What comes next in Alaska

Dunleavy said a smaller batch of ballots is due on Sunday, Nov. 15, ahead of the final count. Alaska counts mail ballots that arrive up to 10 days after Election Day if they were postmarked in time. If no candidate passes 50%, ranked-choice ballots are retabulated after all ballots are counted. Dunleavy also said investigations into possible wrongdoing in the election are under way, according to The Hill.

A fourth name on the ballot, Daniel J. Sullivan, has drawn attention. The Justice Department sued to block certification, arguing the shared name would confuse voters, and a federal judge rejected that suit, Democracy Docket reported. President Trump has called for that candidate''s votes to go to the incumbent, which Democracy Docket noted has no basis in law.

## Mississippi

In Mississippi, Democrat Scott Colom led Republican Sen. Cindy Hyde-Smith by about 2,500 votes on Friday evening, Nov. 6, out of more than 950,000 cast, according to an Associated Press count cited by the Mississippi Free Press. Most of the remaining votes are affidavit ballots.

Tuesday, Nov. 10, is the last day for mail ballots postmarked by Election Day to arrive and for affidavit voters to show ID at their circuit clerk''s office. Harrison County''s election commission meets that morning to rule on its affidavit ballots. Counties must certify their results by Friday, Nov. 13.

Alaska and Mississippi are the only Senate races not yet called. Democrats will hold at least 54 seats in the new Senate.', 'Boston Daily Staff', 'https://upload.wikimedia.org/wikipedia/commons/thumb/6/68/Mount_McKinley,_Denali_National_Park,_Alaska_LCCN2010630667.tif/lossy-page1-1280px-Mount_McKinley,_Denali_National_Park,_Alaska_LCCN2010630667.tif.jpg', 'Denali, also called Mount McKinley, in Denali National Park, Alaska, 2008 (file). Photo: Carol M. Highsmith / Library of Congress via Wikimedia Commons, public domain', 'public_domain', 'newsroom', 'content/2026-11-09.sql', 7, 0, 'newsroom-assistant', '2026-11-09T10:50:00.000Z', '2026-11-09T10:50:00.000Z');
