INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261109-celtics-bucks', 'celtics-beat-bucks-117-97-paul-george-27-tatum-21-milwaukee-1-9', 'newsroom', 'news_story', 'nba', 'EDITORIAL_REVIEW', 0, 'Paul George scores 27 and Jayson Tatum adds 21 as the Celtics pull away from the Bucks 117-97 in Milwaukee', 'Boston opened the third quarter with nine straight points on Sunday, Nov. 8, and led by at least 15 the rest of the way. The Celtics are 8-2, and the Bucks fell to 1-9.', 'The Celtics beat the Milwaukee Bucks 117-97 in Milwaukee on Sunday, Nov. 8.

Paul George led Boston with 27 points. Jayson Tatum scored 21 and sat out the entire fourth quarter, the Associated Press reported.

## How it got away

Milwaukee led 27-25 after the first quarter, but Boston outscored the Bucks 33-18 in the second and led 58-45 at halftime, according to ESPN. The Celtics opened the third quarter with nine straight points to go up by 22 and led by at least 15 points the rest of the game.

Kyle Kuzma led Milwaukee with 27 points. Myles Turner had 3 points, 5 rebounds and a career-high 7 assists, and has made 1 of 15 shots over his past two games, the AP reported.

## Where things stand

The Celtics are 8-2. The Bucks are 1-9, their worst start since the 1993-94 season. Boston plays at Philadelphia on Tuesday, Nov. 10.', 'Boston Daily Staff', 'https://upload.wikimedia.org/wikipedia/commons/thumb/b/b6/Pabst_Building_Milwaukee_from_LOC_ID_Service-pnp-det-4a00000-4a08000-4a08000-4a08079v.jpg/1280px-Pabst_Building_Milwaukee_from_LOC_ID_Service-pnp-det-4a00000-4a08000-4a08000-4a08079v.jpg', 'The Pabst Building in Milwaukee, about 1900-1915 (file). Photo: Detroit Publishing Co. / Library of Congress via Wikimedia Commons, public domain', 'public_domain', 'newsroom', 'content/2026-11-09.sql', 6, 0, 'newsroom-assistant', '2026-11-09T10:50:00.000Z', '2026-11-09T10:50:00.000Z');
