INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261109-patriots-packers', 'packers-beat-patriots-45-27-drake-maye-three-interceptions-jordan-love-372-yards', 'newsroom', 'news_story', 'nfl', 'EDITORIAL_REVIEW', 0, 'Packers 45, Patriots 27: Drake Maye throws three first-half interceptions as Green Bay hands New England its first home loss', 'Jordan Love threw for 372 yards and three touchdowns at Gillette Stadium on Sunday, Nov. 8. The Patriots fell to 5-4 and play the Lions in Germany on Sunday, Nov. 15.', 'The Green Bay Packers beat the Patriots 45-27 at Gillette Stadium on Sunday, Nov. 8, handing New England its first home loss of the season.

Drake Maye threw three interceptions before halftime, two to Xavier McKinney and one to Brandon Cisse, and the Patriots fell behind 17-0 before they scored, according to NBC Sports Boston and Yahoo Sports. Maye finished 21 of 38 for 299 yards and three touchdowns, to Rhamondre Stevenson, Efton Chism III and Mack Hollins.

"Just disappointed in myself," Maye said afterward, adding that he put the team "in a hole, straight off the bat," Yahoo Sports reported.

## Green Bay''s passing game

Jordan Love completed 23 of 39 passes for 372 yards and three touchdowns with no interceptions, and he ran 13 yards for another score, according to Bleacher Report. Christian Watson caught 7 passes for 171 yards and a touchdown, and Matthew Golden had 10 catches for 164 yards and a touchdown. Packers running back Josh Jacobs left early with a broken finger, ESPN reported.

DeMario Douglas led New England with 5 catches for 102 yards. Wide receiver A.J. Brown and running back TreVeyon Henderson did not play.

## Where things stand

The Packers are 6-3, and the Patriots are 5-4. New England faces the Detroit Lions in Germany on Sunday, Nov. 15, at 9:30 a.m. Eastern, then has its bye week, according to NESN. Detroit beat Miami 19-9 on Sunday, Nov. 8.', 'Boston Daily Staff', 'https://upload.wikimedia.org/wikipedia/commons/thumb/a/a4/Lambeau_Field,_Green_Bay,_Wisconsin_(9181850538).jpg/1280px-Lambeau_Field,_Green_Bay,_Wisconsin_(9181850538).jpg', 'Lambeau Field, home of the Green Bay Packers, 2013 (file). Photo: Ken Lund via Wikimedia Commons, CC BY-SA 2.0', 'licensed', 'newsroom', 'content/2026-11-09.sql', 5, 0, 'newsroom-assistant', '2026-11-09T10:50:00.000Z', '2026-11-09T10:50:00.000Z');
