INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261109-bruins-panthers', 'bruins-beat-panthers-4-1-swayman-40-saves-fourth-straight-win-126-penalty-minutes', 'newsroom', 'news_story', 'nhl', 'EDITORIAL_REVIEW', 0, 'Swayman makes 40 saves as the Bruins beat the Panthers 4-1 for their fourth straight win in a game with 126 penalty minutes', 'Boston scored three times in the first period at TD Garden on Sunday, Nov. 8, and improved to 13-4-1, including 8-1-0 at home.', 'Jeremy Swayman made a season-high 40 saves as the Bruins beat the Florida Panthers 4-1 at TD Garden on Sunday, Nov. 8, for their fourth straight win, NHL.com reported.

Elias Lindholm, Michael Eyssimont and Morgan Geekie scored in the first period, and JJ Peterka added a goal in the third. Carter Verhaeghe scored Florida''s only goal, on a power play late in the first period. Jacob Markstrom made 32 saves for the Panthers.

## A rough afternoon

The game produced 126 penalty minutes, including seven 10-minute misconducts, the most in a single game this season, according to Boston Hockey Now. Nikita Zadorov fought two seconds after the opening faceoff, and Mark Kastelic also dropped the gloves. Swayman stopped 13 shots while Boston was shorthanded.

"Sometimes I feel like we don''t even talk enough about our goalies," Bruins coach Marco Sturm said.

## Where things stand

The Bruins are 13-4-1 and 8-1-0 at home, and it was their first win over a division opponent this season. The Panthers are 9-7-2 and have lost three of their past four. Boston hosts Montreal on Thursday, Nov. 12.', 'Boston Daily Staff', 'https://upload.wikimedia.org/wikipedia/commons/thumb/c/cb/Boston_skyline_-_John_Hancock_Tower,_111_Huntington_Avenue_and_Prudential_Tower_from_Charles_River_Dam.jpg/1280px-Boston_skyline_-_John_Hancock_Tower,_111_Huntington_Avenue_and_Prudential_Tower_from_Charles_River_Dam.jpg', 'The Boston skyline from the Charles River Dam, 2017 (file). Photo: Beyond My Ken via Wikimedia Commons, CC BY-SA 4.0', 'licensed', 'newsroom', 'content/2026-11-09.sql', 4, 0, 'newsroom-assistant', '2026-11-09T10:50:00.000Z', '2026-11-09T10:50:00.000Z');
