INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261109-nfl-week9', 'nfl-week-9-results-bengals-beat-falcons-madrid-burrow-chase-texans-chargers-0-8', 'newsroom', 'news_story', 'nfl', 'EDITORIAL_REVIEW', 0, 'Bengals beat the Falcons 34-17 in Madrid for a fourth straight win, and the Chargers fall to 0-8 in Week 9', 'Ja''Marr Chase had 155 receiving yards at the Bernabéu on Sunday, Nov. 8. Houston beat the Chargers 44-22, and Justin Herbert left with a finger injury.', 'The Cincinnati Bengals beat the Atlanta Falcons 34-17 at Real Madrid''s Bernabéu stadium in Madrid on Sunday, Nov. 8, for their fourth straight win, NFL.com reported.

Joe Burrow led four scoring drives in the first half. Ja''Marr Chase had a career-high 142 receiving yards before halftime and finished with 10 catches for 155 yards and a touchdown, and Tee Higgins caught two touchdown passes. Burrow and Chase have now connected on 19 touchdowns of 40 yards or more, tied with Joe Montana and Jerry Rice for the third-most by any quarterback-receiver pair since 1980, according to NFL.com. Bijan Robinson had 147 yards from scrimmage and a touchdown for Atlanta.

The Bengals are 6-2, tied with Pittsburgh atop the AFC North. The Falcons fell to 3-6.

## Sunday''s other results

Final scores, as listed by Pro Football Focus:

- Packers 45, Patriots 27
- Texans 44, Chargers 22
- 49ers 38, Raiders 17
- Chiefs 35, Jets 12
- Cowboys 27, Colts 23
- Broncos 26, Panthers 21
- Saints 23, Browns 22
- Rams 20, Commanders 13
- Lions 19, Dolphins 9
- Giants 19, Eagles 11
- Seahawks 17, Cardinals 3

## Injuries to watch

Chargers quarterback Justin Herbert left the loss to Houston with a finger injury and was having tests, and Los Angeles is still winless. Green Bay running back Josh Jacobs left early with a broken finger, and San Francisco defensive tackle Gracen Halton is out for the season with a broken ankle, ESPN reported. Myles Garrett had three sacks in the Rams'' win at Washington.

Jacksonville beat Baltimore 33-10 on Thursday, Nov. 5, to open the week, and Pittsburgh and Tennessee were on byes.', 'Boston Daily Staff', 'https://upload.wikimedia.org/wikipedia/commons/thumb/1/1f/Panoramic_santiago_bernabeu.jpg/1280px-Panoramic_santiago_bernabeu.jpg', 'The Santiago Bernabéu stadium in Madrid, 2019 (file). Photo: Fernando Pascullo via Wikimedia Commons, CC BY-SA 4.0', 'licensed', 'newsroom', 'content/2026-11-09.sql', 3, 0, 'newsroom-assistant', '2026-11-09T10:50:00.000Z', '2026-11-09T10:50:00.000Z');
